import React, {useEffect, useMemo, useState } from 'react';
import { useUser } from '../UserContext';
const emptyParty = {
  partyID: '',
  partyType: '2', // Supplier is selected by default in your form
  partyName: '',
  address: '',
  contactNo: '',
  active: true,
};

function PartyPage() {
  const user = useUser();
  const connString = user && user.connString;
  const [parties, setParties] = useState([]);
  const [search, setSearch] = useState('');
  const [editingIndex, setEditingIndex] = useState(null);
  const [formParty, setFormParty] = useState(emptyParty);
  const [isAddingParty, setIsAddingParty] = useState(false);
  const [errors, setErrors] = useState({});
  const [partyType, setPartyType] = useState('2');
  const [isLoading, setIsLoading] = useState(Boolean(connString));
    const [loadError, setLoadError] = useState('');
    const [isSaving, setIsSaving] = useState(false);
    const [isUpdatingStatus, setIsUpdatingStatus] = useState(false);
    const [saveError, setSaveError] = useState('');
    const [saveMessage, setSaveMessage] = useState('');
    const [reloadKey, setReloadKey] = useState(0);
useEffect(() => {
    let isActive = true;

    async function loadParties() {
      if (typeof connString !== 'string' || !connString.trim()) {
        setLoadError('Unable to load parties.');
        setIsLoading(false);
        return;
      }

      setIsLoading(true);
      setLoadError('');

      try {
        const response = await fetch('https://api.azkopos.com/Party/GetAllPartyData?TypeID=1', {
          method: 'GET',
          headers: {
            ConnectionString: connString,
          },
        });

        if (!response.ok) {
          throw new Error('Party request failed.');
        }

        const data = await response.json();
        if (!Array.isArray(data) || data.some((item) => (
          !item
          || !Number.isFinite(item.partyID)
          || typeof item.name !== 'string'
          || typeof item.address !== 'string'
          || typeof item.contactNo !== 'string'
          || typeof item.partyType !== 'string'
          || typeof item.status !== 'string'
        ))) {
          throw new Error('User response is invalid.');
        }

        if (isActive) {
          setParties(data.map((item) => ({
            partyID: item.partyID,
            partyType: item.partyType,
            partyName: item.name,
            address: item.address,
            contactNo: item.contactNo,
            active: item.status.toLowerCase() === 'active',
          })));
        }
      } catch {
        if (isActive) {
          setLoadError('Unable to load parties. Please try again.');
        }
      } finally {
        if (isActive) {
          setIsLoading(false);
        }
      }
    }

    loadParties();
    return () => {
      isActive = false;
    };
  }, [connString, reloadKey]);

const filteredParties = useMemo(() => {
    const query = search.trim().toLowerCase();
    return parties
      .map((party, index) => ({ ...party, index }))
      .filter((party) => `${party.partyName} ${party.address} ${party.contactNo}`
        .toLowerCase().includes(query));
  }, [search, parties]);

  const openAddForm = () => {
    setFormParty(emptyParty);
    setEditingIndex(null);
    setErrors({});
    setSaveError('');
    setSaveMessage('');
    setIsAddingUser(true);
  };

  const cancelForm = () => {
    setErrors({});
    setSaveError('');
    setIsAddingUser(false);
  };

  const saveParty = async (event) => {
    event.preventDefault();
    setSaveError('');
    setSaveMessage('');
    const nextErrors = {
      partyName: formParty.partyName.trim() ? '' : 'Party Name is required.',
      address: formParty.address.trim() ? '' : 'Address is required.',
      contactNo: formParty.contactNo.trim() ? '' : 'Contact Number is required.',
      employeeName: formUser.employeeName.trim() ? '' : 'Employee Name is required.',
    };
    setErrors(nextErrors);
    if (Object.values(nextErrors).some(Boolean)) {
      return;
    }

    if (
      typeof connString !== 'string'
      || !connString.trim()
      || !Number.isFinite(user && user.userID)
      || (editingIndex !== null && !Number.isFinite(formUser.userID))
    ) {
      setSaveError('Unable to save user.');
      return;
    }

    setIsSaving(true);
    try {
      const response = await fetch('https://api.azkopos.com/Party/InsertUpdateParty', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ConnectionString: connString,
        },
        body: JSON.stringify({
          PartyID: editingIndex === null ? 0 : formParty.partyID,
          Name: formParty.name,
          Address: formParty.address,
          ContactNo: formParty.contactNo,
          PartyType: Number(formParty.partyType),
          UserID: user.userID,
          TypeID: editingIndex === null ? 1 : 2,
        }),
      });

      if (!response.ok) {
        throw new Error('User save request failed.');
      }

      setSaveMessage('Party saved successfully.');
      setIsAddingParty(false);
      setReloadKey((key) => key + 1);
    } catch {
      setSaveError('Unable to save user. Please try again.');
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="section-page party-page" data-testid="party-page">
      <h1>Setting / Party</h1>
      {!isAddingParty ? (
        <section className="party-card" aria-label="Party list">
          <div className="party-toolbar">
            <input
              className="party-search"
              type="search"
              placeholder="Search Party"
              aria-label="Search Party"
            />
            <button
              className="party-add-button"
              type="button"
              onClick={() => {
                setIsAddingParty(true);
              }}
            >
              Add Party
            </button>
          </div>
          <div className="party-table-wrap">
            <table className="party-table">
              <thead>
                <tr>
                  <th scope="col">Party Name</th>
                  <th scope="col">Address</th>
                  <th scope="col">Contact No</th>
                  <th scope="col">Party Type</th>
                  <th scope="col">Edit</th>
                  <th scope="col">Active/Inactive</th>
                </tr>
              </thead>
              <tbody>
                <tr>
                  <td colSpan="6" className="party-empty-state">No parties available.</td>
                </tr>
              </tbody>
            </table>
          </div>
        </section>
      ) : (
        <section className="party-card" aria-label={editingIndex === null ? 'Add Party' : 'Edit Party'}>
          <form className="party-form" onSubmit={savep} noValidate>
            <fieldset className="party-type-options">
              <legend>Party Type</legend>
              <label>
                <input
                  type="radio"
                  name="partyType"
                  value="1"
                  checked={partyType === '1'}
                  onChange={(event) => setPartyType(event.target.value)}
                />
                Customer
              </label>
              <label>
                <input
                  type="radio"
                  name="partyType"
                  value="2"
                  checked={partyType === '2'}
                  onChange={(event) => setPartyType(event.target.value)}
                />
                Supplier
              </label>
            </fieldset>
            <div className="party-form-field">
              <label htmlFor="party-name">Party Name <span aria-hidden="true">*</span></label>
              <input
                id="party-name"
                type="text"
                placeholder="Party Name"
                value={partyName}
                aria-invalid={Boolean(partyNameError)}
                aria-describedby={partyNameError ? 'party-name-error' : undefined}
                onChange={(event) => {
                  setPartyName(event.target.value);
                  if (event.target.value.trim()) setPartyNameError('');
                }}
              />
              {partyNameError && <span id="party-name-error" className="required-field-error" role="alert">{partyNameError}</span>}
            </div>
            <div className="party-form-field">
              <label htmlFor="party-address">Address</label>
              <input id="party-address" type="text" placeholder="Party Address" />
            </div>
            <div className="party-form-field">
              <label htmlFor="party-contact">Contact No</label>
              <input id="party-contact" type="text" placeholder="Party Contact No" />
            </div>
            <div className="party-form-actions">
              <button className="shop-save-button" type="submit">Save</button>
              <button
                className="shop-cancel-button"
                type="button"
                onClick={() => setIsAddingParty(false)}
              >
                Cancel
              </button>
            </div>
          </form>
        </section>
      )}
    </div>
  );
}

export default PartyPage;
